  /** define break up text */
  function p_break_up_text(t: T): void {
    deleteAll(G.l.Num_G_TextOrder);
    deleteAll(G.l.Num_L_TextSplit);
    t.v.misc1 = "1";
    t.v.misc3 = "";
    while (!eq(letterOf(t.v.misc1, G.v.text_break), "")) {
      t.v.misc2 = "";
      while (!(eq(letterOf(t.v.misc1, G.v.text_break), "|") || (eq(letterOf(t.v.misc1, G.v.text_break), "") || eq(letterOf(t.v.misc1, G.v.text_break), "[")))) {
        t.v.misc2 = (String(t.v.misc2) + letterOf(t.v.misc1, G.v.text_break));
        t.v.misc1 = num(t.v.misc1) + 1;
      }
      if (eq(letterOf(t.v.misc1, G.v.text_break), "[")) {
        if (!eq(letterOf((num(t.v.misc1) + 2), G.v.text_break), "]")) {
          t.v.misc1 = num(t.v.misc1) + 1;
          addTo(G.l.Num_G_TextOrder, (letterOf(t.v.misc1, G.v.text_break) + letterOf((num(t.v.misc1) + 1), G.v.text_break)));
          t.v.misc1 = num(t.v.misc1) + 1;
        } else {
          t.v.misc1 = num(t.v.misc1) + 1;
          addTo(G.l.Num_G_TextOrder, letterOf(t.v.misc1, G.v.text_break));
          t.v.misc1 = num(t.v.misc1) + 1;
        }
      } else {
        addTo(G.l.Num_L_TextSplit, t.v.misc2);
      }
      t.v.misc1 = num(t.v.misc1) + 1;
    }
  }

