  /** define text %s %s %s %s %s %s */
  function p_text(t: T, a_input: Value, a_x: Value, a_y: Value, a_size: Value, a_x_range: Value, a_brains: Value): void {
    t.v.yeag = "";
    G.v.speaker = "0";
    t.v.my_col = "0";
    if (gt(a_brains, "")) {
      t.v.yeag = "0";
      t.v.my_col = a_brains;
    }
    t.v.textmisc3 = "0";
    if (eq(t.costumeName(), "nul")) {
      t.v.textmisc = "1";
      if ((eq(a_y, "") && eq(a_x, ""))) {
        t.setXY(-220, -145);
      } else {
        t.setXY(num(a_x), num(a_y));
      }
      while (!eq(letterOf(t.v.textmisc, a_input), "")) {
        if (gt(a_size, 100)) {
          t.switchCostume("bgi2");
        } else {
          t.switchCostume("bgi");
        }
        if (eq(a_size, "")) {
          t.setSize(80);
        } else {
          t.setSize(num(a_size));
        }
        t.switchCostume("a");
        t.switchCostume(letterOf(t.v.textmisc, a_input));
        if (!eq(letterOf(t.v.textmisc, a_input), " ")) {
          rt.createClone(t, "_myself_");
        }
        if (!(eq(t.costumeName(), "¢") || eq(t.costumeName(), "^"))) {
          t.setXY(t.x + num((9 * num((t.getSize() / 80)))), t.y);
        }
        if (eq(a_x_range, "")) {
          if (gt(t.xPosition(), 220)) {
            t.setXY(t.x, t.y + -16);
            t.setXY(-220, t.y);
          }
        } else {
          if (gt(t.xPosition(), a_x_range)) {
            t.setXY(t.x, t.y + -16);
            t.setXY(num(a_x), t.y);
          }
        }
        t.v.textmisc = num(t.v.textmisc) + 1;
      }
      t.switchCostume("nul");
    }
  }

